import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print(-1)
        return

    n = int(data[0])

    if n == 0:
        print(-1)
        return

    if len(data) < n + 1:
        print(-1)
        return

    marks = list(map(int, data[1:n+1]))

    if not marks:
        print(-1)
        return

    result = []
    for mark in marks:
        if mark < 0:
            print(-1)
            return
        if mark >= 90:
            result.append('A')
        elif mark >= 80:
            result.append('B')
        elif mark >= 70:
            result.append('C')
        elif mark >= 60:
            result.append('D')
        else:
            result.append('F')

    print(' '.join(result))

if __name__ == "__main__":
    main()
